export function coerceToObjectTypeContent(
	...input: readonly (
		| T.ExportStatement
		| T.PropertySignature
		| T.CallSignature
		| T.ConstructSignature
		| T.IndexSignature
		| T.MethodSignature
		| T.ObjectTypeContent
	)[]
): ReturnType<typeof F.buildObjectTypeContent> {
	if (input.length === 1 && isNodeData(input[0]) && input[0].$type === TSKindId.ObjectTypeContent) {
		const data = input[0];
		const stored = (data as unknown as { _content?: unknown })._content;
		const children: readonly unknown[] = stored === undefined ? [] : Array.isArray(stored) ? stored : [stored];
		return F.buildObjectTypeContent(
			{
				separator: (() => {
					const sk = (data as unknown as { _separator?: number; _delimiter?: T.Delimiter })._separator;
					const t = sk === undefined ? undefined : KIND_LITERAL_TEXT.get(sk);
					return t === ',' || t === ';' ? t : undefined;
				})(),
				delimiter: (() => {
					const d = (data as unknown as { _separator?: number; _delimiter?: T.Delimiter })._delimiter;
					return d === Delimiter.Leading || d === Delimiter.Trailing || d === Delimiter.Both ? d : undefined;
				})()
			},
			...(children as unknown as NonEmptyArray<
				| T.ExportStatement
				| T.PropertySignature
				| T.CallSignature
				| T.ConstructSignature
				| T.IndexSignature
				| T.MethodSignature
			>)
		);
	}
	return F.buildObjectTypeContent(
		...(input as unknown as NonEmptyArray<
			| T.ExportStatement
			| T.PropertySignature
			| T.CallSignature
			| T.ConstructSignature
			| T.IndexSignature
			| T.MethodSignature
		>)
	);
}

